CREATE TABLE `ea_tbot_settings` (
  `nclient_id` int(11) NOT NULL COMMENT 'Chính là nid của bảng ea_tbot_client',
  `finitial_lot` double DEFAULT 0.01 COMMENT 'Khối lượng vào lệnh ban đầu',
  `flot_multi` double DEFAULT 1.5 COMMENT 'Hệ số nhân khối lượng Martingale',
  `nmax_orders` int(11) DEFAULT 26 COMMENT 'Số lệnh tối đa trong chuỗi',
  `ntp_mode` int(11) DEFAULT 0 COMMENT '0: Theo Pip, 1: Theo USD',
  `ftp_pips` double DEFAULT 10 COMMENT 'Mục tiêu chốt lời theo Pip',
  `ftp_usd` double DEFAULT 50 COMMENT 'Mục tiêu chốt lời theo USD',
  `nrsi_period` int(11) DEFAULT 14 COMMENT 'Chu kỳ RSI',
  `crsi_tf` varchar(20) DEFAULT 'PERIOD_M1' COMMENT 'Khung thời gian RSI',
  `nmagic` bigint(20) DEFAULT 522345 COMMENT 'Mã nhận diện lệnh Magic Number',
  `cuse_time_filter` char(1) DEFAULT '1' COMMENT '1: Bật khung giờ, 0: Chạy 24/7',
  `csession_asia` char(1) DEFAULT '1' COMMENT 'Sydney - Tokyo (Phiên Á: 05:00 - 14:00): 1=Bật, 0=Tắt',
  `csession_london` char(1) DEFAULT '1' COMMENT 'London (Phiên Âu: 14:00 - 23:00): 1=Bật, 0=Tắt',
  `csession_ny` char(1) DEFAULT '1' COMMENT 'New York (Phiên Mỹ: 19:00 - 04:00): 1=Bật, 0=Tắt',
  `ctime_start_1` varchar(10) DEFAULT '' COMMENT 'Khung giờ 1: Giờ bắt đầu (HH:mm)',
  `ctime_end_1` varchar(10) DEFAULT '' COMMENT 'Khung giờ 1: Giờ kết thúc (HH:mm)',
  `ctime_start_2` varchar(10) DEFAULT '' COMMENT 'Khung giờ 2: Giờ bắt đầu (HH:mm)',
  `ctime_end_2` varchar(10) DEFAULT '' COMMENT 'Khung giờ 2: Giờ kết thúc (HH:mm)',
  `ctime_start_3` varchar(10) DEFAULT '' COMMENT 'Khung giờ 3: Giờ bắt đầu (HH:mm)',
  `ctime_end_3` varchar(10) DEFAULT '' COMMENT 'Khung giờ 3: Giờ kết thúc (HH:mm)',
  `nstart_hour_local` int(11) DEFAULT 6 COMMENT 'Giờ bắt đầu giao dịch theo giờ VN',
  `nend_hour_local` int(11) DEFAULT 4 COMMENT 'Giờ dừng giao dịch theo giờ VN',
  `nmin_before_close` int(11) DEFAULT 60 COMMENT 'Phút trước EndHour: giữ basket, không mở L1/thêm lệnh',
  `nconfirm_from_order` int(11) DEFAULT 10 COMMENT 'Từ lệnh thứ N trở đi cần xác nhận 2 lần',
  `cpair_close_bat_tat` char(1) DEFAULT '0' COMMENT 'Bật tắt chức năng chốt cặp cắt tỉa',
  `npair_close_tu_lenh` int(11) DEFAULT 9 COMMENT 'Bắt đầu áp dụng từ lệnh thứ N',
  `fpair_close_so_usd` double DEFAULT 2 COMMENT 'Mức lợi nhuận USD để chốt cặp',
  `cpair_close_chot_dan_ve` char(1) DEFAULT '0' COMMENT '1: chốt liên tiếp nhiều cặp (chốt dần về), 0: Tắt',
  `fbasket_tp_phan_tram` double DEFAULT 0 COMMENT 'Tỷ lệ % trailing chốt lời chuỗi',
  `cstep_distances` text DEFAULT NULL COMMENT 'Cấu hình mảng JSON cho các bước G1 đến G25'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=COMPACT;

